<?php
declare(strict_types=1);require_once __DIR__.'/../config/bootstrap.php';requireRole('student');header('Content-Type: application/json; charset=utf-8');$uid=userId();$s=$pdo->prepare('SELECT id,full_name,email,language,xp,level,streak FROM users WHERE id=?');$s->execute([$uid]);$user=$s->fetch();$s=$pdo->prepare('SELECT c.id,c.slug,c.title_en,c.title_ar,p.completed_lessons,p.total_lessons,p.percent_complete FROM progress p JOIN courses c ON c.id=p.course_id WHERE p.student_id=? ORDER BY c.id');$s->execute([$uid]);$courses=$s->fetchAll();foreach($courses as &$c)$c['title']=lang()==='ar'?$c['title_ar']:$c['title_en'];echo json_encode(['user'=>$user,'courses'=>$courses]);
